static const char *const TAG = "amble_spike2";
AmbleSpike2 *global_spike2 = nullptr;  // NOLINT

// ---- node composition -------------------------------------------------------
// Receive-only posture: no relay, no beacons, no GATT proxy. The bridge ran with
// relay + proxy on; whether the product should is a Spike 2 finding, not a given.
static esp_ble_mesh_cfg_srv_t config_server = {
    .net_transmit = ESP_BLE_MESH_TRANSMIT(2, 20),
    .relay = ESP_BLE_MESH_RELAY_DISABLED,
    .relay_retransmit = ESP_BLE_MESH_TRANSMIT(2, 20),
    .beacon = ESP_BLE_MESH_BEACON_DISABLED,
    .gatt_proxy = ESP_BLE_MESH_GATT_PROXY_DISABLED,
    .default_ttl = 7,
};

static esp_ble_mesh_model_op_t vnd_op[] = {
    ESP_BLE_MESH_MODEL_OP(ESP_BLE_MESH_MODEL_OP_3(telink::OPCODE, telink::COMPANY_ID), 1),
    ESP_BLE_MESH_MODEL_OP(telink::OPCODE, 1),
    ESP_BLE_MESH_MODEL_OP_END,
};
static esp_ble_mesh_model_t root_models[] = {ESP_BLE_MESH_MODEL_CFG_SRV(&config_server)};
static esp_ble_mesh_model_t vnd_models[] = {
    ESP_BLE_MESH_VENDOR_MODEL(telink::COMPANY_ID, telink::VENDOR_MODEL_ID, vnd_op, NULL, NULL)};
static esp_ble_mesh_elem_t elements[] = {ESP_BLE_MESH_ELEMENT(0, root_models, vnd_models)};
static esp_ble_mesh_comp_t composition = {.cid = telink::COMPANY_ID, .element_count = 1, .elements = elements};
static uint8_t dev_uuid[16] = {'a', 'm', 'b', 'l', 'e', '-', 's', 'p', 'i', 'k', 'e', '2', 0, 0, 0, 0};
static esp_ble_mesh_prov_t provision = {.uuid = dev_uuid};

static void prov_cb(esp_ble_mesh_prov_cb_event_t event, esp_ble_mesh_prov_cb_param_t *param) {
  switch (event) {
    case ESP_BLE_MESH_PROV_REGISTER_COMP_EVT:
      ESP_LOGI(TAG, "mesh stack registered (err %d)", param->prov_register_comp.err_code);
      break;
    case ESP_BLE_MESH_NODE_PROV_COMPLETE_EVT:
      ESP_LOGI(TAG, "node provisioned: net_idx %u", param->node_prov_complete.net_idx);
      break;
    default:
      ESP_LOGD(TAG, "prov event %d", (int) event);
  }
}

static void model_cb(esp_ble_mesh_model_cb_event_t event, esp_ble_mesh_model_cb_param_t *param) {
  if (event == ESP_BLE_MESH_MODEL_OPERATION_EVT) {
    ESP_LOGI(TAG, "message addressed to us: op 0x%06lx len %u", (unsigned long) param->model_operation.opcode,
             param->model_operation.length);
  } else if (event == ESP_BLE_MESH_MODEL_SEND_COMP_EVT) {
    ESP_LOGD(TAG, "send complete err %d", param->model_send_comp.err_code);
  }
}

// ---- lifecycle ----------------------------------------------------------------
void AmbleSpike2::setup() {
  global_spike2 = this;
  // Standing rule 2 (strict reading): no mesh addresses in log lines; fixtures are
  // labelled "target" (the bench fixture) or "other" (anything else on the mesh).
  ESP_LOGI(TAG, "node up, transmit %s", this->transmit_ ? "ENABLED" : "off (receive-only)");
}

void AmbleSpike2::loop() {
  if (this->mesh_started_ || this->mesh_failed_)
    return;
  if (esp32_ble::global_ble == nullptr || !esp32_ble::global_ble->is_active())
    return;
  if (!this->start_mesh_()) {
    this->mesh_failed_ = true;
    return;
  }
  this->mesh_started_ = true;
}

bool AmbleSpike2::start_mesh_() {
  esp_err_t err = esp_ble_mesh_register_prov_callback(prov_cb);
  if (err == ESP_OK)
    err = esp_ble_mesh_register_custom_model_callback(model_cb);
  if (err == ESP_OK)
    err = esp_ble_mesh_init(&provision, &composition);
  if (err != ESP_OK) {
    ESP_LOGE(TAG, "mesh init failed: %s", esp_err_to_name(err));
    return false;
  }
  return this->self_provision_();
}

// Self-provision with the imported keys, or pick up the state the stack restored
// from NVS (CONFIG_BLE_MESH_SETTINGS). Mirrors the bridge; IDF 5.5 split
// bt_mesh_provision() into pre_provision() + provision().
bool AmbleSpike2::self_provision_() {
  if (bt_mesh_is_provisioned()) {
    ESP_LOGI(TAG, "mesh state restored from NVS: seq %lu iv_index %lu", (unsigned long) bt_mesh.seq,
             (unsigned long) bt_mesh.iv_index);
    char note[80];
    snprintf(note, sizeof(note), "restored from NVS: seq %lu iv %lu", (unsigned long) bt_mesh.seq,
             (unsigned long) bt_mesh.iv_index);
    this->boot_note_ = note;
  } else {
    esp_err_t err = esp_ble_mesh_node_prov_enable((esp_ble_mesh_prov_bearer_t) (ESP_BLE_MESH_PROV_ADV | ESP_BLE_MESH_PROV_GATT));
    if (err != ESP_OK) {
      ESP_LOGE(TAG, "node_prov_enable: %s", esp_err_to_name(err));
      return false;
    }
    uint8_t dev_key[16];
    esp_fill_random(dev_key, sizeof(dev_key));  // only used for Config traffic we never do
    int rc = bt_mesh_pre_provision(AMARAN_NET_KEY, 0, 0, 0, this->own_address_, dev_key);
    if (rc != 0) {
      ESP_LOGE(TAG, "bt_mesh_pre_provision rc=%d", rc);
      return false;
    }
    bt_mesh_provision();
    esp_ble_mesh_node_prov_disable((esp_ble_mesh_prov_bearer_t) (ESP_BLE_MESH_PROV_ADV | ESP_BLE_MESH_PROV_GATT));
    ESP_LOGI(TAG, "self-provisioned (fresh), seq %lu", (unsigned long) bt_mesh.seq);
    char note[80];
    snprintf(note, sizeof(note), "fresh self-provision: seq %lu", (unsigned long) bt_mesh.seq);
    this->boot_note_ = note;
  }
  int rc = bt_mesh_node_local_app_key_add(0, 0, AMARAN_APP_KEY);
  ESP_LOGI(TAG, "app key add rc=%d (0 ok, -EEXIST fine)", rc);
  rc = bt_mesh_node_bind_app_key_to_model(bt_mesh_primary_addr(), telink::VENDOR_MODEL_ID, telink::COMPANY_ID, 0);
  ESP_LOGI(TAG, "app key bind rc=%d", rc);
  return true;
}

void AmbleSpike2::dump_config() {
  ESP_LOGCONFIG(TAG, "amble spike 2: mesh %s, transmit %s, snooped %lu (target %lu), sent %lu",
                this->mesh_started_ ? "up" : "down", this->transmit_ ? "on" : "off", (unsigned long) this->snooped_total_,
                (unsigned long) this->snooped_target_, (unsigned long) this->sent_total_);
}

uint32_t AmbleSpike2::mesh_seq() const { return this->mesh_started_ ? bt_mesh.seq : 0; }
uint32_t AmbleSpike2::mesh_iv_index() const { return this->mesh_started_ ? bt_mesh.iv_index : 0; }

// ---- sending (guarded) -----------------------------------------------------------
bool AmbleSpike2::send_telink_(const uint8_t payload[10]) {
  constexpr uint16_t dst = AMARAN_TARGET_ADDR;
  // Standing rule 1: unicast to the one bench fixture, nothing else, ever.
  static_assert(dst >= 0x0002 && dst < 0x8000, "target must be a unicast address");
  if (!this->transmit_) {
    ESP_LOGW(TAG, "transmit disabled; command dropped");
    return false;
  }
  if (!this->mesh_started_)
    return false;
  esp_ble_mesh_msg_ctx_t ctx = {};
  ctx.net_idx = 0;
  ctx.app_idx = 0;
  ctx.addr = dst;
  ctx.send_ttl = 7;
  uint32_t seq_before = bt_mesh.seq;
  esp_err_t err = esp_ble_mesh_server_model_send_msg(&vnd_models[0], &ctx, telink::OPCODE, 10, (uint8_t *) payload);
  ESP_LOGI(TAG, "send op 0x26 -> target type 0x%02x err=%d seq %lu->%lu", payload[9], err,
           (unsigned long) seq_before, (unsigned long) bt_mesh.seq);
  if (err == ESP_OK)
    this->sent_total_++;
  return err == ESP_OK;
}

bool AmbleSpike2::send_onoff(bool on) {
  uint8_t p[10];
  telink::onoff(on, p);
  return this->send_telink_(p);
}
bool AmbleSpike2::send_brightness(uint16_t v) {
  uint8_t p[10];
  telink::brightness(v, p);
  return this->send_telink_(p);
}
bool AmbleSpike2::send_cct(uint16_t k, uint16_t v, int gm) {
  uint8_t p[10];
  telink::cct(k, v, gm, p);
  return this->send_telink_(p);
}
bool AmbleSpike2::send_hsi(uint16_t h, uint8_t s, uint16_t v) {
  uint8_t p[10];
  telink::hsi(h, s, v, p);
  return this->send_telink_(p);
}
bool AmbleSpike2::send_status_request() {
  uint8_t p[10];
  telink::status_request(p);
  return this->send_telink_(p);
}

// ---- snoop: decoded access payload arrives here (BTC task) -------------------------
void AmbleSpike2::on_access_payload(uint16_t src, uint16_t dst, uint32_t seq, const uint8_t *data, uint16_t len) {
  const uint8_t *p = nullptr;
  if (len == 11 && data[0] == telink::OPCODE) {
    p = data + 1;  // 1-byte opcode form (what the fixtures use)
  } else if (len == 13 && data[0] == (0xC0 | telink::OPCODE) && data[1] == (telink::COMPANY_ID & 0xff) &&
             data[2] == (telink::COMPANY_ID >> 8)) {
    p = data + 3;  // 3-byte vendor form
  } else {
    ESP_LOGD(TAG, "access from %s seq %lu len %u op 0x%02x (not Telink status)", src == AMARAN_TARGET_ADDR ? "target" : "other",
             (unsigned long) seq, len, len ? data[0] : 0);
    return;
  }
  this->snooped_total_++;
  FixtureStatus st;
  if (!telink::decode_status(p, &st)) {
    ESP_LOGD(TAG, "%s seq %lu Telink type 0x%02x (not a state report)", src == AMARAN_TARGET_ADDR ? "target" : "other",
             (unsigned long) seq, p[9] & 0x7f);
    return;
  }
  const char *who = src == AMARAN_TARGET_ADDR ? "target" : "other";
  char text[96];
  if (st.is_hs) {
    snprintf(text, sizeof(text), "%s %s HSI hue=%u sat=%u int=%u", who, st.on ? "on" : "off", st.hue, st.sat,
             st.intensity);
  } else {
    snprintf(text, sizeof(text), "%s %s CCT %uK gm=%d int=%u", who, st.on ? "on" : "off", st.cct_kelvin, st.gm,
             st.intensity);
  }
  ESP_LOGI(TAG, "status %s (seq %lu)", text, (unsigned long) seq);
  (void) dst;
  if (src == AMARAN_TARGET_ADDR) {
    this->snooped_target_++;
    this->last_target_status_ = st;
    std::lock_guard<std::mutex> lock(this->text_mutex_);
    this->last_status_text_ = text;
  }
}

